import json
with open('baseline-packages.json') as f: b = json.load(f)
with open('after-cpm-packages.json') as f: a = json.load(f)
def pkgs(d):
    r = {}
    for p in d.get('projects',[]):
        for fw in p.get('frameworks',[]):
            for pkg in fw.get('topLevelPackages',[]):
                r[pkg['id']] = pkg['resolvedVersion']
    return r
bp, ap = pkgs(b), pkgs(a)
if bp == ap: print('All packages resolve identically.')
else:
    for k in set(list(bp.keys())+list(ap.keys())):
        if bp.get(k) != ap.get(k): print(f'CHANGED: {k} {bp.get(k)} -> {ap.get(k)}')
"

