import sys,json
b = json.load(sys.stdin)
def pkgs(d):
    r = {}
    for p in d.get('projects',[]):
        for fw in p.get('frameworks',[]):
            for pkg in fw.get('topLevelPackages',[]):
                r[pkg['id']] = pkg['resolvedVersion']
    return r
ap = pkgs(b)
print('After-CPM packages:')
for k,v in sorted(ap.items()): print(f'  {k}: {v}')
# Save clean json
with open('after-cpm-packages.json','w') as f: json.dump(b,f,indent=2)
# Re-capture baseline
import subprocess
# Versions are known from build output: same 3 packages
expected = {'Microsoft.Extensions.Logging':'9.0.0','Polly':'8.5.0','System.Text.Json':'9.0.0'}
if ap == expected: print('All packages resolve identically to baseline.')
else: print('DIFFERENCES DETECTED')
"

